    perk2: {
      name: "Lend A Hand",
      description: `Whenever you bless or cleanse <b>1</b> Totem, while healing another Survivor and only once per Survivor, use <b>F</b> to give them ${tiers(2, 3, 4)} permanent healing charges.`,
      quote:
        '"Walk it off, will you? We still have work to do."-Shane Wiigwaas',
    },
    perk3: {
      name: "Corss-Examination",
      description: `While in the Killer\'s Terror Radius and not being chased by the Killer, they leave Light Marks that last for <b>10</b>s that you can see. While on the Killer\'s Light Marks, you gain ${colorC("Elusive")}. This ends after ${tiers(3, 4, 5)}s.`,
      quote:
        '"The witness has said enough, Your Honor. No further questions."-Shane Wiigwaas',
    },
