(function () {
  const container = document.getElementById("iconsContainer");
  const text = document.getElementById("progressText");
  const fill = document.getElementById("progressFill");
  if (!container || !text || !fill) return;

  function update() {
    const total = container.querySelectorAll(".icon").length;
    const done = container.querySelectorAll(".icon.checked").length;
    const type = localStorage.getItem("currentType") || "killers";
    const label = type === "killers" ? "Killer" : "Survivor";
    text.textContent = `${done} / ${total} ${label} Adepts`;
    fill.style.width = total ? (done / total) * 100 + "%" : "0%";

    document.querySelectorAll(".buttons button").forEach((button) => {
      button.classList.toggle(
        "active",
        button.textContent.trim().toLowerCase() === type,
      );
    });
  }

  new MutationObserver(update).observe(container, {
    childList: true,
    subtree: true,
    attributes: true,
    attributeFilter: ["class"],
  });

  update();
})();

function createIcons(type) {
  const container = document.getElementById("iconsContainer");
  container.innerHTML = "";

  const icons = type === "killers" ? killerIcons : survivorIcons;

  icons.forEach((icon, index) => {
    const div = document.createElement("div");
    div.className = "icon";
    div.dataset.name = icon.name;
    div.onclick = () => toggleCheck(div, index);
    div.addEventListener("pointerenter", () => loadPerkImages(div), {
      once: true,
    });

    const img = document.createElement("img");
    img.loading = "lazy";
    img.decoding = "async";
    img.src = icon.src;
    img.alt = icon.name;
    div.appendChild(img);

    const overlay = document.createElement("div");
    overlay.className = "icon-overlay";
    const span = document.createElement("span");
    span.textContent = icon.name;
    overlay.appendChild(span);

    const imagesContainer = document.createElement("div");
    imagesContainer.className = "icon-images";

    perkTooltips[icon.name] = [];

    if (icon.hoverImages && icon.hoverImages.length === 3) {
      icon.hoverImages.forEach((src, i) => {
        const img = document.createElement("img");
        img.src = BLANK_IMG;
        img.dataset.src = src;
        img.alt = `${icon.name} - Hover ${i + 1}`;

        const wrapper = document.createElement("div");
        wrapper.className =
          "img-wrapper perk-bg" + (i === 2 ? " bottom-img" : "");
        wrapper.appendChild(img);

        const tooltip = document.createElement("div");
        tooltip.className = "perk-tooltip";

        const perkName = document.createElement("h3");
        perkName.textContent = getPerkName(icon.name, i + 1);
        tooltip.appendChild(perkName);

        const dividerContainer = document.createElement("div");
        dividerContainer.className = "divider-container";

        const divider = document.createElement("div");
        divider.className = "divider";

        dividerContainer.appendChild(divider);
        tooltip.appendChild(dividerContainer);

        const characterInfo = document.createElement("div");
        characterInfo.className = "character-info";

        const characterName = document.createElement("div");
        characterName.className = "character-name";
        characterName.textContent = icon.name;

        const rarity = document.createElement("div");
        rarity.className = "rarity";
        rarity.textContent = "TEACHABLE";

        characterInfo.appendChild(characterName);
        characterInfo.appendChild(rarity);
        tooltip.appendChild(characterInfo);

        const description = document.createElement("p");
        description.innerHTML = getPerkDescription(icon.name, i + 1);
        tooltip.appendChild(description);

        const quoteText = getPerkQuote(icon.name, i + 1);

        if (quoteText && quoteText.trim() !== '""') {
          const quote = document.createElement("div");
          quote.className = "quote";
          quote.textContent = quoteText;
          tooltip.appendChild(quote);
        }

        document.body.appendChild(tooltip);
        perkTooltips[icon.name].push(tooltip);
        imagesContainer.appendChild(wrapper);

        attachPerkTooltip(img, tooltip);
      });
    }

    overlay.appendChild(imagesContainer);
    div.appendChild(overlay);

    div.classList.add("has-info");

    const infoBtn = document.createElement("button");
    infoBtn.className = "info-btn";
    infoBtn.type = "button";
    infoBtn.textContent = "i";
    infoBtn.setAttribute("aria-label", `Info about ${icon.name}`);
    infoBtn.onclick = (e) => {
      e.stopPropagation();
      openCharacterInfo(icon, type);
    };
    div.appendChild(infoBtn);

    container.appendChild(div);
  });

  currentType = type;
  localStorage.setItem("currentType", type);
  loadState();
}

function toggleCheck(element) {
  element.classList.toggle("checked");
  saveState();
}

function saveState() {
  const icons = document.querySelectorAll(".icon");
  const checkedStates = {};

  icons.forEach((icon) => {
    if (icon.classList.contains("checked")) {
      const name = icon.dataset.name;
      checkedStates[name] = true;
    }
  });

  localStorage.setItem(
    `checkedIcons_${currentType}`,
    JSON.stringify(checkedStates),
  );
}

function loadState() {
  const icons = document.querySelectorAll(".icon");
  const checkedStates =
    JSON.parse(localStorage.getItem(`checkedIcons_${currentType}`)) || {};

  icons.forEach((icon) => {
    const name = icon.dataset.name;
    if (checkedStates[name]) {
      icon.classList.add("checked");
    } else {
      icon.classList.remove("checked");
    }
  });
}

function filterIcons() {
  const input = document.getElementById("search").value.toLowerCase();
  const icons = document.querySelectorAll(".icon");

  icons.forEach((icon) => {
    const alt = icon.querySelector("img").alt.toLowerCase();
    icon.style.display = alt.includes(input) ? "block" : "none";
  });
}

/* -------------------------------------------------------------------------- */
/*                                    Hooks                                   */
/* -------------------------------------------------------------------------- */

window.onload = () => {
  createIcons(currentType);
  loadState();
};
